import com.rs2.cache.js5.*; import com.rs2.model.music.*;import com.rs2.net.packet.*; import java.io.*;
public class MusicCoverage {public static void main(String[] a)throws Exception{Interfaces.load();MusicTrackDefinition.loadDefinitions();try(Js5CacheStore s=new Js5CacheStore(new File("cache"))){for(java.util.Map.Entry<Integer,Music.Track> e:Music.tracks().entrySet()){Music.Track t=e.getValue();try{if(t.assetId<0)throw new IOException("no named asset");s.readFiles(6,t.assetId);}catch(Exception ex){System.out.println("UNAVAILABLE "+e.getKey()+" "+t.name+" asset="+t.assetId+" legacy="+t.legacyId+" mapped="+AudioIds443.track(t.legacyId));}}}}}
